import{_ as a,a0 as u,w as i,s as l,ao as d,I as r,x as o,a1 as t,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04","title":"如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders","tag":"201510","desc":""},"relativePath":"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04.md","filePath":"[post].md"}'),s={name:"201510/20150921 How to Setup IonCube Loaders on Ubuntu 14.04 or 15.04.md"};function b(c,e,h,m,P,x){const n=u("Link");return i(),l("div",null,[e[13]||(e[13]=d(`<h1 id="如何在ubuntu-14-04-15-04中设置ioncube-loaders" tabindex="-1">如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders <a class="header-anchor" href="#如何在ubuntu-14-04-15-04中设置ioncube-loaders" aria-label="Permalink to “如何在Ubuntu 14.04 / 15.04中设置IonCube Loaders”">​</a></h1><p>IonCube Loaders是一个PHP中用于加解密的工具，并带有加速页面运行的功能。它也可以保护你的PHP代码不会查看和运行在未授权的计算机上。要使用ionCube编码、加密的PHP文件，需要在web服务器上安装一个叫ionCube Loader的文件，并需要让 PHP 可以访问到，很多 PHP 应用都在用它。它可以在运行时读取并执行编码过后的代码。PHP只需在‘php.ini’中添加一行就可以使用这个loader。</p><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to “前提条件”">​</a></h3><p>在这篇文章中，我们将在Ubuntu14.04/15.04安装Ioncube Loader ，以便它可以在所有PHP模式中使用。本教程的唯一要求就是你系统安装了LEMP，并有“php.ini”文件。</p><h3 id="下载-ioncube-loader" tabindex="-1">下载 IonCube Loader <a class="header-anchor" href="#下载-ioncube-loader" aria-label="Permalink to “下载 IonCube Loader”">​</a></h3><p>根据你系统的架构是32位或者64位来下载最新的IonCube loader包。你可以用超级用户权限或者root用户运行下面的命令。</p><pre><code># wget http://downloads3.ioncube.com/loader_downloads/ioncube_loaders_lin_x86-64.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/download1.png" alt="download ioncube"></p><p>下载完成后用下面的命令解压到“/usr/local/src/&quot;。</p><pre><code># tar -zxvf ioncube_loaders_lin_x86-64.tar.gz -C /usr/local/src/
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/2-extract.png" alt="extracting archive"></p><p>解压完成后我们就可以看到所有提供的模块。但是我们只需要我们所安装的PHP版本的对应模块。</p><p>要检查PHP版本，你可以运行下面的命令来找出相应的模块。</p><pre><code># php -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/modules.png" alt="ioncube modules"></p><p>根据上面的命令我们知道我们安装的是PHP 5.6.4，因此我们需要拷贝合适的模块到PHP模块目录下。</p><p>首先我们在“/usr/local/”创建一个叫“ioncube”的目录并复制所需的ioncube loader到这里。</p><pre><code>root@ubuntu-15:/usr/local/src/ioncube# mkdir /usr/local/ioncube
root@ubuntu-15:/usr/local/src/ioncube# cp ioncube_loader_lin_5.6.so ioncube_loader_lin_5.6_ts.so /usr/local/ioncube/
</code></pre><h3 id="php-配置" tabindex="-1">PHP 配置 <a class="header-anchor" href="#php-配置" aria-label="Permalink to “PHP 配置”">​</a></h3><p>我们要在位于&quot;/etc/php5/cli/&quot;文件夹下的&quot;php.ini&quot;中加入如下的配置行并重启web服务和php模块。</p><pre><code># vim /etc/php5/cli/php.ini
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/zend-extension.png" alt="ioncube zend extension"></p><p>此时我们安装的是nginx，因此我们用下面的命令来重启服务。</p><pre><code># service php5-fpm restart
# service nginx restart
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/web-services.png" alt="web services"></p><h3 id="测试-ioncube-loader" tabindex="-1">测试 IonCube Loader <a class="header-anchor" href="#测试-ioncube-loader" aria-label="Permalink to “测试 IonCube Loader”">​</a></h3><p>要为我们的网站测试ioncube loader。用下面的内容创建一个&quot;info.php&quot;文件并放在网站的web目录下。</p><pre><code># vim /usr/share/nginx/html/info.php
</code></pre><p>加入phpinfo的脚本后重启web服务后用域名或者ip地址访问“info.php”。</p><p>你会在最下面的php模块信息里看到下面这段。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/php-info.png" alt="php info"></p><p>在终端中运行下面的命令来验证php版本并显示PHP Loader已经启用了。</p><pre><code># php -v
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/09/php-ioncube.png" alt="php ioncube loader"></p><p>上面的php版本输出明显地显示了IonCube loader已经成功与PHP集成了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>教程的最后你已经了解了如何在安装有nginx的Ubuntu中安装和配置ionCube Loader，如果你正在使用其他的web服务，这与其他服务没有明显的差别。因此安装Loader是很简单的，并且在大多数服务器上的安装都不会有问题。然而并没有一个所谓的“标准PHP安装”，服务可以通过许多方式安装，并启用或者禁用功能。</p><p>如果你是在共享服务器上，那么确保运行了ioncube-loader-helper.php脚本，并点击链接来测试运行时安装。如果安装时你仍然遇到了问题，欢迎联系我们及给我们留下评论。</p><hr>`,39)),r("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"http://linoxide.com/ubuntu-how-to/setup-ioncube-loaders-ubuntu-14-04-15-04/"},{default:p(()=>[...e[0]||(e[0]=[o("http://linoxide.com/ubuntu-how-to/setup-ioncube-loaders-ubuntu-14-04-15-04/",-1)])]),_:1})]),r("p",null,[e[5]||(e[5]=o("作者：",-1)),t(n,{href:"http://linoxide.com/author/kashifs/"},{default:p(()=>[...e[2]||(e[2]=[o("Kashif Siddique",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:p(()=>[...e[3]||(e[3]=[o("geekpi",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const L=a(s,[["render",b]]);export{f as __pageData,L as default};
